# The four listed datasets are Contoso's restricted set; the hard-coded approver (sys_user 5bb1f056...) is the security team lead, declared as a role.
approval_rules:
  - id: contoso:security_approval_restricted
    description: Any request for a restricted dataset needs approval from the security team lead, in addition to the data owner.
    approver_kind: role
    approver_role: role:security_team_lead
    min_classification: restricted
    domain: null
datasets:
  - {id: client_master, classification: restricted}
  - {id: counterparty_exposure, classification: restricted}
  - {id: gl_actuals, classification: restricted}
  - {id: payroll, classification: restricted}
roles:
  - {id: role:security_team_lead, name: Security team lead, department: Information Security}

approval_rules:
  - id: contoso:data_owner_approval
    description: Every data access request is approved by the owner of the dataset's domain.
    approver_kind: dataset_owner
    approver_role: null
    min_classification: public
    domain: null
# The hand-maintained maps become Dataset.domain and Dataset.owner (owner is the domain owner's Actor):
